import 'react-native-gesture-handler';
import { AppRegistry } from 'react-native';
import App from './App';
import { name as appName } from './app.json';


AppRegistry.registerComponent(appName, () => App);
// iOS builds generated by EAS/Expo prebuild launch the root component named "main"
// (Expo convention). Android keeps using `appName` via MainActivity. Register both
// so iOS doesn't crash/blank on launch with "Application main has not been registered".
AppRegistry.registerComponent('main', () => App);
